typing.fullText:
properties {
        @notation(adjective)
        surjective: Prop {
            forall b in range,
            exists a in domain
            |- apply(a) = b
        }
        @notation(adjective)
        injective: Prop {
            forall a_1 a_2 in domain
            |- a_1 != a_2 -> apply(a_1) != apply(a_2)
        }
        @notation(adjective)
        bijective: (surjective, injective)
        ...
    }
    laws {
        domain_def {
            forall a in domain |- apply(a) in range
        }
    }
